(()=>{'use strict';const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0)),data=new DataView(bytes.buffer),vertexCount=data.getUint32(0,true),count=data.getUint32(4,true);window.__baileVenusRefine=g=>{if(g.userData.baileSurfaceRefined||g.attributes.position.count!==vertexCount)return;const p=g.attributes.position.array,n=g.attributes.normal.array;for(let i=0;i<count;i++){const offset=8+i*28,index=data.getUint32(offset,true)*3;for(let axis=0;axis<3;axis++){p[index+axis]=data.getFloat32(offset+4+axis*4,true);n[index+axis]=data.getFloat32(offset+16+axis*4,true)}}g.attributes.position.needsUpdate=true;g.attributes.normal.needsUpdate=true;g.userData.baileSurfaceRefined={vertices:count,patches:2}}})();
